suite('guestTransplant: branch GC sweep (AC7)', function () {

    test('a transplant PR in ANY closed state deletes its branch; an OPEN one is left alone', function () {
        var steps = mod.gcSteps([
            { branch: 'ai/guest-1', prState: 'MERGED' },
