    var url = 'https://github.com/' + full + '/pull/' + String(o.sourcePrNumber);
    var lines = [
        'Transplants guest PR ' + full + '#' + String(o.sourcePrNumber) +
            ' (' + sanitizeGuestTitle(o.sourceTitle, 200) + ') by ' +
